import 'dart:convert';

import 'package:crypto/crypto.dart' show sha256;
import 'package:flutter_tools/src/shorebird/shorebird_ed25519.dart';
import 'package:flutter_tools/src/shorebird/shorebird_release_trust.dart';

// GENERATED by shorebird-workspace scripts/release_trust.py from
// scripts/testdata/release-trust/*.DEVELOPMENT-ONLY.* (root seed [1]*32,
// build-manifest seed [7]*32, the artifact-catalog development key). The
// updater pins the same bytes (release_trust.rs `PYTHON_BUNDLE`).
const kDevelopmentRootPin =
    '';
const kDevelopmentBundle =
    r'{"contract_version":2,"delegations":{"payload":"","signatures":[{"key_id":"sha256:34750f98bd59fcfc946da45aaabe933be154a4b5094e1c4abf42866505f3c97e","signature":"b6745pQEKi8Xtxpx7W396VjoZVQe1QtMqKaZRVxRIqRhnO96WgRx++Yqw1YxMMGNWdFX6XpVyCBJP8kclKwYBA=="}]},"root_chain":[{"payload":"","signatures":[{"key_id":"sha256:34750f98bd59fcfc946da45aaabe933be154a4b5094e1c4abf42866505f3c97e","signature":"D4NJujR/sYdsGal8U/zV8EQV8rMefW8QDv6sXuC/TGt/+6bp+diiU/U20pb+uUa2hlpiVCLlmqMpooT/arrWDg=="}]}],"schema":"open-shorebird.release-trust"}';

/// Fixed DEVELOPMENT-ONLY test seeds, the same as the updater's tests.
List<int> seed(int byte) => List<int>.filled(32, byte);
final List<int> rootSeed = seed(1);
final List<int> nextRootSeed = seed(2);
final List<int> catalogSeed = seed(3);
final List<int> manifestSeed = seed(7);
final List<int> nextManifestSeed = seed(8);
final List<int> strangerSeed = seed(9);

String keyId(List<int> seed) => shorebirdReleaseKeyId(ed25519PublicKey(seed));

Map<String, Object?> _key(List<int> seed) => <String, Object?>{
  'key_id': keyId(seed),
  'public_key': base64.encode(ed25519PublicKey(seed)),
};

String rootPayload(
  int version,
  List<List<int>> seeds, {
  int threshold = 1,
  String expiresAt = '2036-11-09T00:00:00Z',
}) => shorebirdCanonicalJson(<String, Object?>{
  'schema': 'open-shorebird.release-root',
  'contract_version': 2,
  'version': version,
  'threshold': threshold,
  'keys': <Object?>[for (final List<int> s in seeds) _key(s)],
  'expires_at': expiresAt,
});

String delegationsPayload(
  int version,
  int rootVersion, {
  List<List<int>> manifest = const <List<int>>[],
  List<List<int>> catalog = const <List<int>>[],
  List<String> catalogPublicKeys = const <String>[],
  List<String> manifestPublicKeys = const <String>[],
  List<String> revoked = const <String>[],
  String issuedAt = '2026-11-01T00:00:00Z',
  String expiresAt = '2036-11-01T00:00:00Z',
  String notBefore = '2026-11-01T00:00:00Z',
  String notAfter = '2036-11-01T00:00:00Z',
}) {
  Map<String, Object?> window(Map<String, Object?> key) => <String, Object?>{
    ...key,
    'not_before': notBefore,
    'not_after': notAfter,
  };
  List<Object?> keys(List<List<int>> seeds, List<String> publicKeys) => <Object?>[
    for (final List<int> s in seeds) window(_key(s)),
    for (final String public in publicKeys)
      window(<String, Object?>{
        'key_id': shorebirdReleaseKeyId(base64.decode(public)),
        'public_key': public,
      }),
  ];
  return shorebirdCanonicalJson(<String, Object?>{
    'schema': 'open-shorebird.release-delegations',
    'contract_version': 2,
    'version': version,
    'root_version': rootVersion,
    'issued_at': issuedAt,
    'expires_at': expiresAt,
    'roles': <String, Object?>{
      'build-manifest': keys(manifest, manifestPublicKeys),
      'artifact-catalog': keys(catalog, catalogPublicKeys),
    },
    'revoked_key_ids': revoked,
  });
}

Map<String, Object?> envelope(String domain, String payload, List<List<int>> signers) {
  final List<int> bytes = utf8.encode(payload);
  final List<int> message = utf8.encode('$domain${sha256.convert(bytes)}');
  return <String, Object?>{
    'payload': base64.encode(bytes),
    'signatures': <Object?>[
      for (final List<int> s in signers)
        <String, Object?>{'key_id': keyId(s), 'signature': base64.encode(ed25519Sign(s, message))},
    ],
  };
}

String bundle(List<Map<String, Object?>> rootChain, Map<String, Object?> delegations) =>
    shorebirdCanonicalJson(<String, Object?>{
      'schema': 'open-shorebird.release-trust',
      'contract_version': 2,
      'root_chain': rootChain,
      'delegations': delegations,
    });

/// An operator (non-development) root [2]*32 delegating manifest key
/// [7]*32 and catalog key [3]*32.
final String operatorRoot = rootPayload(1, <List<int>>[nextRootSeed]);
String operatorBundle({
  List<List<int>> manifest = const <List<int>>[],
  int version = 1,
  List<String> revoked = const <String>[],
  String notBefore = '2026-11-01T00:00:00Z',
  String notAfter = '2036-11-01T00:00:00Z',
}) => bundle(
  const <Map<String, Object?>>[],
  envelope(
    kShorebirdReleaseDelegationsSignatureDomain,
    delegationsPayload(
      version,
      1,
      manifest: manifest.isEmpty ? <List<int>>[manifestSeed] : manifest,
      catalog: <List<int>>[catalogSeed],
      revoked: revoked,
      notBefore: notBefore,
      notAfter: notAfter,
    ),
    <List<int>>[nextRootSeed],
  ),
);
